function Badge({children}:{children:string}){return <span className="badge">{children}</span>}
function Shell({children}:{children:ReactNode}){const[open,setOpen]=useState(false);return <div className="min-h-screen bg-[#f6f2e9] lg:flex"><aside className={(open?"translate-x-0":"-translate-x-full")+" fixed inset-y-0 left-0 z-[60] w-[270px] border-r border-black/5 bg-[#fbf7ef] p-5 transition-transform lg:static lg:z-auto lg:translate-x-0"}><div className="flex items-center justify-between"><Link to="/admin" onClick={()=>setOpen(false)}><div className="eyebrow">Administration</div><div className="mt-1 font-serif text-2xl text-forest">Grand Courtyard</div></Link><button className="p-2 lg:hidden" onClick={()=>setOpen(false)}><X size={19}/></button></div><div className="mt-8 rounded-2xl bg-forest p-4 text-white"><div className="text-xs text-white/55">Current workspace</div><div className="mt-1 font-semibold">Hotel Operations</div><div className="mt-1 text-xs text-white/55">Demo mode · Firebase later</div></div><nav className="mt-6 space-y-1">{nav.map(([path,label,Icon])=><NavLink key={path} to={path} end={path==="/admin"} onClick={()=>setOpen(false)} className={({isActive})=>"flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm "+(isActive?"bg-white font-semibold text-forest shadow-sm":"text-ink/55 hover:bg-white/70")}><Icon size={17}/><span>{label}</span></NavLink>)}</nav><Link to="/" className="mt-6 flex items-center gap-3 px-3 py-2.5 text-sm text-ink/50"><LogOut size={17}/>Back to website</Link></aside>{open&&<button className="fixed inset-0 z-50 bg-black/30 lg:hidden" onClick={()=>setOpen(false)}/>}<div className="min-w-0 flex-1"><header className="sticky top-0 z-40 border-b border-black/5 bg-[#f6f2e9]/90 backdrop-blur"><div className="flex h-[74px] items-center justify-between px-5 sm:px-8"><button className="rounded-xl border bg-white p-2.5 lg:hidden" onClick={()=>setOpen(true)}><Menu size={19}/></button><div className="hidden max-w-md flex-1 items-center gap-3 rounded-xl border bg-white px-3 sm:flex"><Search size={17} className="text-ink/35"/><input className="w-full bg-transparent py-2 text-sm outline-none" placeholder="Search bookings, guests, rooms..."/></div><div className="ml-auto flex items-center gap-3"><button className="rounded-xl border bg-white p-2.5"><Bell size={18}/></button><div className="flex items-center gap-3 rounded-xl border bg-white px-3 py-2"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-forest text-xs font-bold text-white">GC</div><div className="hidden sm:block"><div className="text-sm font-semibold text-forest">Hotel Admin</div><div className="text-[11px] text-ink/40">Demo administrator</div></div></div></div></div></header><main className="p-5 sm:p-8">{children}</main></div></div>}
function Head({eyebrow,title,body,action}:{eyebrow:string;title:string;body:string;action?:ReactNode}){return <div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="eyebrow">{eyebrow}</div><h1 className="section-title mt-2 text-forest">{title}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-ink/55">{body}</p></div>{action}</div>}
function Modal({title,children,onClose}:{title:string;children:ReactNode;onClose:()=>void}){return <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/45 p-4"><div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-[28px] bg-white p-6 shadow-2xl sm:p-8"><div className="flex items-center justify-between"><h2 className="font-serif text-2xl text-forest">{title}</h2><button onClick={onClose} className="rounded-xl border p-2"><X size={18}/></button></div>{children}</div></div>}
function Metric({label,value,change,icon:Icon}:{label:string;value:string;change:string;icon:typeof BarChart3}){return <div className="rounded-[24px] border border-black/5 bg-white p-5 shadow-sm"><div className="flex justify-between"><div><div className="text-sm text-ink/45">{label}</div><div className="mt-2 text-2xl font-semibold text-forest">{value}</div><div className="mt-2 text-xs text-ink/45">{change}</div></div><div className="rounded-2xl bg-cream p-3 text-gold"><Icon size={19}/></div></div></div>}

function Overview(){const bs=load("gc-admin-bookings",bookingSeed);const confirmed=bs.filter((b:Booking)=>b.status!=="Cancelled").length;return <><Head eyebrow="Saturday · 26 September 2026" title="Good afternoon." body="Here is what is happening across The Grand Courtyard today." action={<Link className="btn-primary" to="/admin/bookings">Manage bookings <ChevronRight size={16}/></Link>}/><div className="mt-8 rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900"><strong>Demo mode:</strong> changes are saved in this browser only. Firebase can replace this data layer later.</div><div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Today's revenue" value={money(53460)} change="Demo operational figure" icon={CircleDollarSign}/><Metric label="Bookings" value={String(confirmed)} change="Live from demo state" icon={CalendarDays}/><Metric label="Occupancy" value="76%" change="19 of 25 rooms occupied" icon={BedDouble}/><Metric label="Guests" value="42" change="Demo operational figure" icon={Users}/></div><div className="mt-6 rounded-[26px] border border-black/5 bg-white p-6"><div className="flex items-center justify-between"><div><h2 className="font-semibold text-forest">Recent bookings</h2><p className="mt-1 text-xs text-ink/40">Latest reservation activity</p></div><Link className="text-sm font-semibold text-forest" to="/admin/bookings">View all</Link></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="border-b border-black/5 text-xs text-ink/40"><tr><th className="pb-3">Booking</th><th className="pb-3">Guest</th><th className="pb-3">Room</th><th className="pb-3">Amount</th><th className="pb-3">Status</th></tr></thead><tbody>{bs.slice(0,5).map((b:Booking)=><tr key={b.id} className="border-b border-black/5 last:border-0"><td className="py-4 font-semibold text-forest">{b.id}</td><td className="py-4">{b.guest}</td><td className="py-4 text-ink/55">{b.room}</td><td className="py-4">{money(b.amount)}</td><td className="py-4"><Badge>{b.status}</Badge></td></tr>)}</tbody></table></div></div></>}

function Bookings(){const[items,setItems]=useState<Booking[]>(()=>load("gc-admin-bookings",bookingSeed));const[filter,setFilter]=useState("All");const[q,setQ]=useState("");const[selected,setSelected]=useState<Booking|null>(null);const[notice,setNotice]=useState("");const filtered=useMemo(()=>items.filter(b=>(filter==="All"||b.status===filter)&&[b.id,b.guest,b.room,b.email].join(" ").toLowerCase().includes(q.toLowerCase())),[items,filter,q]);
const update=(id:string,patch:Partial<Booking>)=>{const next=items.map(b=>b.id===id?{...b,...patch}:b);setItems(next);save("gc-admin-bookings",next);const changed=next.find(b=>b.id===id);if(changed)setSelected(changed);setNotice("Booking updated");setTimeout(()=>setNotice(""),1800)};
return <><Head eyebrow="Reservations" title="Booking management" body="Search reservations, inspect guest details and move each stay through its operational status." action={<button className="btn-primary" onClick={()=>setNotice("New booking creation will connect to the customer booking flow later.")}>New booking</button>}/>{notice&&<div className="mt-5 flex items-center gap-2 rounded-2xl bg-green-50 p-4 text-sm text-green-800"><CheckCircle2 size={17}/>{notice}</div>}<div className="mt-6 flex flex-col gap-3 rounded-[24px] border border-black/5 bg-white p-4 md:flex-row"><div className="flex flex-1 items-center gap-3 rounded-xl border border-black/10 px-3"><Search size={17} className="text-ink/35"/><input className="w-full bg-transparent py-2 outline-none" placeholder="Search booking, guest, room or email" value={q} onChange={e=>setQ(e.target.value)}/></div><select className="input md:w-48" value={filter} onChange={e=>setFilter(e.target.value)}><option>All</option><option>Confirmed</option><option>Pending</option><option>Checked in</option><option>Checked out</option><option>Cancelled</option></select></div><div className="mt-5 overflow-x-auto rounded-[26px] border border-black/5 bg-white"><table className="w-full min-w-[980px] text-left text-sm"><thead className="border-b border-black/5 text-xs text-ink/40"><tr>{["Booking","Guest","Room","Stay","Amount","Payment","Status",""].map(x=><th key={x} className="px-5 py-4">{x}</th>)}</tr></thead><tbody>{filtered.map(b=><tr key={b.id} className="border-b border-black/5 last:border-0"><td className="px-5 py-4 font-semibold text-forest">{b.id}</td><td className="px-5 py-4"><div>{b.guest}</div><div className="text-xs text-ink/40">{b.email}</div></td><td className="px-5 py-4 text-ink/55">{b.room}</td><td className="px-5 py-4 text-xs text-ink/55">{b.checkIn}<br/>→ {b.checkOut}</td><td className="px-5 py-4 font-semibold">{money(b.amount)}</td><td className="px-5 py-4"><Badge>{b.payment}</Badge></td><td className="px-5 py-4"><Badge>{b.status}</Badge></td><td className="px-5 py-4"><button className="font-semibold text-forest" onClick={()=>setSelected(b)}>View</button></td></tr>)}</tbody></table>{filtered.length===0&&<div className="p-10 text-center text-sm text-ink/45">No bookings match your search.</div>}</div>{selected&&<Modal title={"Reservation "+selected.id} onClose={()=>setSelected(null)}><div className="mt-6 grid gap-4 sm:grid-cols-2"><div className="rounded-2xl bg-cream p-5"><div className="text-xs text-ink/40">Guest</div><div className="mt-2 font-semibold text-forest">{selected.guest}</div><div className="mt-1 text-sm">{selected.email}</div><div className="text-sm">{selected.phone}</div><div className="mt-2 text-sm">{selected.guests} guest{selected.guests===1?"":"s"}</div></div><div className="rounded-2xl bg-cream p-5"><div className="text-xs text-ink/40">Stay</div><div className="mt-2 font-semibold text-forest">{selected.room}</div><div className="mt-1 text-sm">{selected.checkIn} → {selected.checkOut}</div><div className="mt-2 text-xl font-semibold text-forest">{money(selected.amount)}</div></div></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-sm">Booking status<select className="input mt-2" value={selected.status} onChange={e=>update(selected.id,{status:e.target.value as Booking["status"]})}><option>Pending</option><option>Confirmed</option><option>Checked in</option><option>Checked out</option><option>Cancelled</option></select></label><label className="text-sm">Payment status<select className="input mt-2" value={selected.payment} onChange={e=>update(selected.id,{payment:e.target.value as Booking["payment"]})}><option>Pending</option><option>Paid</option><option>Failed</option><option>Refunded</option></select></label></div><div className="mt-6 flex flex-wrap gap-3"><button className="btn-primary" onClick={()=>update(selected.id,{status:"Confirmed",payment:selected.payment==="Pending"?"Paid":selected.payment})}>Confirm booking</button><button className="btn-secondary" onClick={()=>update(selected.id,{status:"Checked in"})}>Check in</button><button className="btn-secondary" onClick={()=>update(selected.id,{status:"Checked out"})}>Check out</button><button className="rounded-xl border border-red-200 px-4 py-2.5 text-sm font-semibold text-red-700" onClick={()=>update(selected.id,{status:"Cancelled",payment:selected.payment==="Paid"?"Refunded":selected.payment})}>Cancel booking</button></div></Modal>}</>}

function Rooms(){const[items,setItems]=useState<Room[]>(()=>load("gc-admin-rooms",roomSeed));const[q,setQ]=useState("");const[editing,setEditing]=useState<Room|null>(null);const[adding,setAdding]=useState(false);const[form,setForm]=useState<Room>(roomSeed[0]);const filtered=items.filter(r=>r.name.toLowerCase().includes(q.toLowerCase()));const openForm=(r?:Room)=>{setForm(r?{...r}:{name:"",type:"Deluxe",price:0,capacity:2,status:"Available",featured:false,amenities:"King bed · Wi-Fi"});r?setEditing(r):setAdding(true)};const saveRoom=()=>{if(!form.name.trim()||form.price<=0)return;const next=editing?items.map(r=>r.name===editing.name?form:r):[...items,form];setItems(next);save("gc-admin-rooms",next);setEditing(null);setAdding(false)};const remove=(name:string)=>{if(!confirm("Remove this room from the demo inventory?"))return;const next=items.filter(r=>r.name!==name);setItems(next);save("gc-admin-rooms",next)};return <><Head eyebrow="Inventory" title="Rooms" body="Manage room types, pricing, capacity, amenities, status and featured inventory." action={<button className="btn-primary" onClick={()=>openForm()}>Add room</button>}/><div className="mt-6 flex items-center gap-3 rounded-xl border border-black/10 bg-white px-3 sm:max-w-sm"><Search size={17} className="text-ink/35"/><input className="w-full bg-transparent py-3 outline-none" placeholder="Search rooms" value={q} onChange={e=>setQ(e.target.value)}/></div><div className="mt-5 grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{filtered.map(r=><div className="overflow-hidden rounded-[26px] border border-black/5 bg-white" key={r.name}><div className="h-28 bg-gradient-to-br from-[#e9dfcc] to-[#cbb995]"/><div className="p-5"><div className="flex justify-between gap-4"><div><div className="font-semibold text-forest">{r.name}</div><div className="mt-1 text-xs text-ink/45">{r.type} · up to {r.capacity} guests</div></div><Badge>{r.status}</Badge></div><p className="mt-4 text-xs leading-5 text-ink/50">{r.amenities}</p><div className="mt-5 flex items-end justify-between"><div><div className="text-2xl font-semibold text-forest">{money(r.price)}</div><div className="text-xs text-ink/40">per night {r.featured&&"· Featured"}</div></div><div className="flex gap-2"><button className="btn-secondary min-h-9 px-3 text-xs" onClick={()=>openForm(r)}>Edit</button><button className="rounded-xl border p-2 text-red-600" onClick={()=>remove(r.name)} aria-label={"Delete "+r.name}><Trash2 size={15}/></button></div></div></div></div>)}</div>{(editing||adding)&&<Modal title={editing?"Edit room":"Add room"} onClose={()=>{setEditing(null);setAdding(false)}}><div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="text-sm">Room name<input className="input mt-2" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label className="text-sm">Room type<input className="input mt-2" value={form.type} onChange={e=>setForm({...form,type:e.target.value})}/></label><label className="text-sm">Price / night<input className="input mt-2" type="number" min="1" value={form.price} onChange={e=>setForm({...form,price:Number(e.target.value)})}/></label><label className="text-sm">Capacity<input className="input mt-2" type="number" min="1" value={form.capacity} onChange={e=>setForm({...form,capacity:Number(e.target.value)})}/></label><label className="text-sm">Status<select className="input mt-2" value={form.status} onChange={e=>setForm({...form,status:e.target.value as Room["status"]})}><option>Available</option><option>Maintenance</option><option>Inactive</option></select></label><label className="text-sm">Featured<select className="input mt-2" value={String(form.featured)} onChange={e=>setForm({...form,featured:e.target.value==="true"})}><option value="true">Yes</option><option value="false">No</option></select></label><label className="text-sm sm:col-span-2">Amenities<textarea className="input mt-2 min-h-24" value={form.amenities} onChange={e=>setForm({...form,amenities:e.target.value})}/></label></div><div className="mt-6 flex justify-end gap-3"><button className="btn-secondary" onClick={()=>{setEditing(null);setAdding(false)}}>Cancel</button><button className="btn-primary" onClick={saveRoom}>Save room</button></div></Modal>}</>}

