function Gallery(){
 const[items,setItems]=useState<GalleryItem[]>(()=>load("gc-admin-gallery",gallerySeed));
 const[category,setCategory]=useState<"All"|GalleryCategory>("All");
 const[q,setQ]=useState("");
 const[editing,setEditing]=useState<GalleryItem|null>(null);
 const[adding,setAdding]=useState(false);
 const[notice,setNotice]=useState("");
 const[form,setForm]=useState<GalleryItem>(gallerySeed[0]);
 const filtered=useMemo(()=>[...items].sort((a,b)=>a.order-b.order).filter(i=>(category==="All"||i.category===category)&&[i.id,i.title,i.category,i.alt].join(" ").toLowerCase().includes(q.toLowerCase())),[items,category,q]);
 const notify=(message:string)=>{setNotice(message);setTimeout(()=>setNotice(""),2200)};
 const persist=(next:GalleryItem[])=>{const normalized=next.map((x,i)=>({...x,order:i+1}));setItems(normalized);save("gc-admin-gallery",normalized)};
 const openAdd=()=>{setForm({id:"IMG-"+String(Date.now()).slice(-6),title:"",category:"Hotel",url:"",featured:false,order:items.length+1,alt:""});setAdding(true)};
 const openEdit=(item:GalleryItem)=>{setForm({...item});setEditing(item)};
 const saveItem=()=>{if(!form.title.trim()||!form.url.trim()){notify("Add a title and image first");return}const next=editing?items.map(i=>i.id===editing.id?{...form}:i):[...items,{...form,order:items.length+1}];persist(next);setEditing(null);setAdding(false);notify(editing?"Image updated":"Image added")};
 const remove=(id:string)=>{if(!confirm("Delete this gallery image from the demo library?"))return;persist(items.filter(i=>i.id!==id));setEditing(null);notify("Image deleted")};
 const move=(id:string,direction:-1|1)=>{const sorted=[...items].sort((a,b)=>a.order-b.order);const index=sorted.findIndex(i=>i.id===id);const target=index+direction;if(index<0||target<0||target>=sorted.length)return;[sorted[index],sorted[target]]=[sorted[target],sorted[index]];persist(sorted);notify("Gallery order updated")};
 const handleUpload=(file:File|null)=>{if(!file)return;if(!file.type.startsWith("image/")){notify("Please choose an image file");return}if(file.size>1500000){notify("For demo mode, use an image under 1.5 MB");return}const reader=new FileReader();reader.onload=()=>{setForm(f=>({...f,url:String(reader.result),title:f.title||file.name.replace(/\\.[^/.]+$/,""),alt:f.alt||file.name.replace(/\\.[^/.]+$/,"")}));notify("Image loaded — save the item to add it")};reader.readAsDataURL(file)};
 const featured=items.filter(i=>i.featured).length;
 return <><Head eyebrow="Hotel media" title="Gallery management" body="Organize hotel, room and restaurant photography, upload new images, feature key photos and control their display order." action={<button className="btn-primary" onClick={openAdd}>Add image</button>}/>
 {notice&&<div className="mt-5 flex items-center gap-2 rounded-2xl bg-green-50 p-4 text-sm text-green-800"><CheckCircle2 size={17}/>{notice}</div>}
 <div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
   <Metric label="Total images" value={String(items.length)} change="Demo gallery library" icon={ImageIcon}/>
   <Metric label="Hotel" value={String(items.filter(i=>i.category==="Hotel").length)} change="Property photography" icon={ImageIcon}/>
   <Metric label="Rooms" value={String(items.filter(i=>i.category==="Rooms").length)} change="Room photography" icon={BedDouble}/>
   <Metric label="Featured" value={String(featured)} change="Highlighted across the gallery" icon={Star}/>
 </div>
 <div className="mt-6 flex flex-col gap-3 rounded-[24px] border border-black/5 bg-white p-4 md:flex-row">
   <div className="flex flex-1 items-center gap-3 rounded-xl border border-black/10 px-3"><Search size={17} className="text-ink/35"/><input className="w-full bg-transparent py-2 outline-none" placeholder="Search image title, category or alt text" value={q} onChange={e=>setQ(e.target.value)}/></div>
   <select className="input md:w-48" value={category} onChange={e=>setCategory(e.target.value as "All"|GalleryCategory)}><option>All</option><option>Hotel</option><option>Rooms</option><option>Restaurant</option></select>
 </div>
 <div className="mt-5 grid gap-5 sm:grid-cols-2 xl:grid-cols-3">
   {filtered.map((item,index)=><div key={item.id} className="overflow-hidden rounded-[26px] border border-black/5 bg-white shadow-sm">
     <div className="relative aspect-[16/10] overflow-hidden bg-cream"><img src={item.url} alt={item.alt||item.title} className="h-full w-full object-cover" onError={e=>{e.currentTarget.style.display="none"}}/><div className="absolute left-3 top-3 flex gap-2"><Badge>{item.category}</Badge>{item.featured&&<Badge>Featured</Badge>}</div><div className="absolute right-3 top-3 rounded-lg bg-black/60 px-2 py-1 text-[11px] text-white">#{item.order}</div></div>
     <div className="p-5"><div className="flex items-start justify-between gap-3"><div><div className="font-semibold text-forest">{item.title}</div><div className="mt-1 text-xs text-ink/40">{item.id}</div></div><button className="rounded-xl border p-2 text-gold" onClick={()=>openEdit(item)} aria-label={"Edit "+item.title}><Settings size={15}/></button></div>
       <p className="mt-3 line-clamp-2 text-xs leading-5 text-ink/50">{item.alt||"No alt text added"}</p>
       <div className="mt-5 flex items-center justify-between gap-2"><div className="flex gap-2"><button className="rounded-xl border p-2 disabled:opacity-30" disabled={index===0} onClick={()=>move(item.id,-1)} aria-label="Move image up">↑</button><button className="rounded-xl border p-2 disabled:opacity-30" disabled={index===filtered.length-1} onClick={()=>move(item.id,1)} aria-label="Move image down">↓</button></div><div className="flex gap-2"><button className="btn-secondary min-h-9 px-3 text-xs" onClick={()=>openEdit(item)}>Edit</button><button className="rounded-xl border p-2 text-red-600" onClick={()=>remove(item.id)} aria-label={"Delete "+item.title}><Trash2 size={15}/></button></div></div>
     </div>
   </div>)}
 </div>
 {filtered.length===0&&<div className="mt-5 rounded-[24px] bg-white p-10 text-center text-sm text-ink/45">No gallery images match your filters.</div>}
 {(editing||adding)&&<Modal title={editing?"Edit gallery image":"Add gallery image"} onClose={()=>{setEditing(null);setAdding(false)}}>
   <div className="mt-6 rounded-2xl border-2 border-dashed border-black/10 bg-cream p-5 text-center">
     {form.url?<img src={form.url} alt="Preview" className="mx-auto max-h-52 rounded-xl object-cover"/>:<div className="mx-auto flex h-32 max-w-md items-center justify-center rounded-xl border border-black/5 bg-white text-ink/35"><ImageIcon size={30}/></div>}
     <label className="btn-secondary mt-4 inline-flex cursor-pointer items-center gap-2"><ImageIcon size={16}/>Choose image<input type="file" accept="image/*" className="hidden" onChange={e=>handleUpload(e.target.files?.[0]||null)}/></label>
     <p className="mt-2 text-xs text-ink/40">Demo upload stores a small image in this browser. Use JPG/PNG/WebP under 1.5 MB.</p>
   </div>
   <div className="mt-6 grid gap-4 sm:grid-cols-2">
     <label className="text-sm sm:col-span-2">Image title<input className="input mt-2" value={form.title} onChange={e=>setForm({...form,title:e.target.value})} placeholder="e.g. Sunset Courtyard"/></label>
     <label className="text-sm">Category<select className="input mt-2" value={form.category} onChange={e=>setForm({...form,category:e.target.value as GalleryCategory})}><option>Hotel</option><option>Rooms</option><option>Restaurant</option></select></label>
     <label className="text-sm">Image URL<input className="input mt-2" value={form.url} onChange={e=>setForm({...form,url:e.target.value})} placeholder="https://..."/></label>
     <label className="text-sm sm:col-span-2">Alt text<input className="input mt-2" value={form.alt} onChange={e=>setForm({...form,alt:e.target.value})} placeholder="Describe the image for accessibility"/></label>
     <label className="flex items-center justify-between rounded-xl border border-black/5 bg-cream p-4 text-sm sm:col-span-2"><span><span className="font-semibold text-forest">Featured image</span><span className="mt-1 block text-xs text-ink/45">Highlight this photo in the public gallery.</span></span><input type="checkbox" checked={form.featured} onChange={e=>setForm({...form,featured:e.target.checked})} className="h-5 w-5"/></label>
   </div>
   <div className="mt-6 flex flex-wrap justify-between gap-3"><div>{editing&&<button className="rounded-xl border border-red-200 px-4 py-2.5 text-sm font-semibold text-red-700" onClick={()=>remove(editing.id)}>Delete image</button>}</div><div className="flex gap-3"><button className="btn-secondary" onClick={()=>{setEditing(null);setAdding(false)}}>Cancel</button><button className="btn-primary" onClick={saveItem}>{editing?"Save changes":"Add image"}</button></div></div>
 </Modal>}
 </>;
}

type CouponType="Percentage"|"Fixed";
type Coupon={id:string;code:string;description:string;type:CouponType;value:number;minSpend:number;expires:string;usageLimit:number;redemptions:number;active:boolean};

const couponSeed:Coupon[]=[
{id:"CPN-001",code:"WELCOME10",description:"10% off for new guests",type:"Percentage",value:10,minSpend:3000,expires:"30 Sep 2026",usageLimit:100,redemptions:42,active:true},
{id:"CPN-002",code:"COURTYARD500",description:"Flat ₹500 stay discount",type:"Fixed",value:500,minSpend:5000,expires:"15 Oct 2026",usageLimit:50,redemptions:18,active:true},
{id:"CPN-003",code:"WEEKEND15",description:"Weekend stay promotion",type:"Percentage",value:15,minSpend:6000,expires:"31 Oct 2026",usageLimit:25,redemptions:25,active:false},
{id:"CPN-004",code:"FESTIVE1000",description:"Festive season flat discount",type:"Fixed",value:1000,minSpend:8000,expires:"20 Dec 2026",usageLimit:200,redemptions:73,active:true}
];

const couponMoney=(c:Coupon)=>c.type==="Percentage"?c.value+"%":money(c.value);
const couponExpired=(date:string)=>{const d=new Date(date);return !Number.isNaN(d.getTime())&&d.getTime()<Date.now()};
const couponUsage=(c:Coupon)=>c.usageLimit>0?Math.min(100,Math.round(c.redemptions/c.usageLimit*100)):0;

function Coupons(){
 const[coupons,setCoupons]=useState<Coupon[]>(()=>load("gc-admin-coupons",couponSeed));
 const[q,setQ]=useState(""); const[filter,setFilter]=useState("All"); const[selected,setSelected]=useState<Coupon|null>(null); const[adding,setAdding]=useState(false); const[editing,setEditing]=useState<Coupon|null>(null); const[notice,setNotice]=useState("");
 const blank:Coupon={id:"",code:"",description:"",type:"Percentage",value:10,minSpend:0,expires:"",usageLimit:100,redemptions:0,active:true};
 const[form,setForm]=useState<Coupon>(blank);
 const notify=(m:string)=>{setNotice(m);setTimeout(()=>setNotice(""),2000)};
 const persist=(next:Coupon[])=>{setCoupons(next);save("gc-admin-coupons",next)};
 const openAdd=()=>{setForm({...blank,id:"CPN-"+String(Date.now()).slice(-6)});setAdding(true);setEditing(null)};
 const openEdit=(c:Coupon)=>{setForm({...c});setEditing(c);setAdding(false)};
 const saveCoupon=()=>{const code=form.code.trim().toUpperCase();if(!code||form.value<=0||!form.expires||form.usageLimit<1){notify("Complete the coupon details before saving");return}if(form.type==="Percentage"&&form.value>100){notify("Percentage discount cannot exceed 100%");return}const duplicate=coupons.some(c=>c.code===code&&c.id!==form.id);if(duplicate){notify("That coupon code already exists");return}const next=editing?coupons.map(c=>c.id===editing.id?{...form,code}:c):[...coupons,{...form,code}];persist(next);setAdding(false);setEditing(null);setSelected(null);notify(editing?"Coupon updated":"Coupon created")};
 const remove=(id:string)=>{if(!confirm("Delete this coupon from the demo promotion list?"))return;persist(coupons.filter(c=>c.id!==id));setSelected(null);setEditing(null);notify("Coupon deleted")};
 const toggle=(id:string)=>{const next=coupons.map(c=>c.id===id?{...c,active:!c.active}:c);persist(next);const changed=next.find(c=>c.id===id);if(changed)setSelected(changed);notify(changed?.active?"Coupon activated":"Coupon deactivated")};
 const redeem=(id:string)=>{const c=coupons.find(x=>x.id===id);if(!c)return;if(c.redemptions>=c.usageLimit){notify("Usage limit reached");return}const next=coupons.map(x=>x.id===id?{...x,redemptions:x.redemptions+1}:x);persist(next);const changed=next.find(x=>x.id===id);if(changed)setSelected(changed);notify("Demo redemption recorded")};
 const filtered=useMemo(()=>coupons.filter(c=>{const expired=couponExpired(c.expires);const state=filter==="All"||filter==="Active"?(filter==="All"||c.active&&!expired):filter==="Inactive"?(!c.active&&!expired):filter==="Expired"?expired:false;return state&&[c.id,c.code,c.description].join(" ").toLowerCase().includes(q.toLowerCase())}),[coupons,filter,q]);
 const active=coupons.filter(c=>c.active&&!couponExpired(c.expires)).length; const expired=coupons.filter(c=>couponExpired(c.expires)).length; const redemptions=coupons.reduce((s,c)=>s+c.redemptions,0); const usageLimit=coupons.reduce((s,c)=>s+c.usageLimit,0);
 return <><Head eyebrow="Promotions" title="Coupon management" body="Create discount codes, control their availability, set expiry and usage limits, and track redemption activity." action={<button className="btn-primary" onClick={openAdd}>Create coupon</button>}/>
 {notice&&<div className="mt-5 flex items-center gap-2 rounded-2xl bg-green-50 p-4 text-sm text-green-800"><CheckCircle2 size={17}/>{notice}</div>}
 <div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Active coupons" value={String(active)} change="Currently available" icon={Percent}/><Metric label="Total coupons" value={String(coupons.length)} change="Demo promotion library" icon={ClipboardList}/><Metric label="Redemptions" value={String(redemptions)} change={"Across "+coupons.length+" coupons"} icon={CheckCircle2}/><Metric label="Expired" value={String(expired)} change="Past expiry date" icon={CalendarDays}/></div>
 <div className="mt-6 flex flex-col gap-3 rounded-[24px] border border-black/5 bg-white p-4 md:flex-row"><div className="flex flex-1 items-center gap-3 rounded-xl border border-black/10 px-3"><Search size={17} className="text-ink/35"/><input className="w-full bg-transparent py-2 outline-none" placeholder="Search code, description or ID" value={q} onChange={e=>setQ(e.target.value)}/></div><select className="input md:w-48" value={filter} onChange={e=>setFilter(e.target.value)}><option>All</option><option>Active</option><option>Inactive</option><option>Expired</option></select></div>
 <div className="mt-5 overflow-x-auto rounded-[26px] border border-black/5 bg-white"><table className="w-full min-w-[1050px] text-left text-sm"><thead className="border-b border-black/5 text-xs text-ink/40"><tr>{["Coupon","Discount","Minimum spend","Expiry","Usage","Status",""].map(x=><th key={x} className="px-5 py-4">{x}</th>)}</tr></thead><tbody>{filtered.map(c=>{const expired=couponExpired(c.expires);return <tr key={c.id} className="border-b border-black/5 last:border-0"><td className="px-5 py-4"><div className="font-semibold tracking-wide text-forest">{c.code}</div><div className="mt-1 text-xs text-ink/40">{c.description} · {c.id}</div></td><td className="px-5 py-4 font-semibold">{couponMoney(c)}</td><td className="px-5 py-4">{c.minSpend?money(c.minSpend):"No minimum"}</td><td className="px-5 py-4 text-xs text-ink/50">{c.expires}</td><td className="px-5 py-4"><div className="min-w-32"><div className="flex justify-between text-xs"><span>{c.redemptions}/{c.usageLimit}</span><span>{couponUsage(c)}%</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-ink/10"><div className="h-full bg-forest" style={{width:couponUsage(c)+"%"}}/></div></div></td><td className="px-5 py-4"><Badge>{expired?"Expired":c.active?"Active":"Inactive"}</Badge></td><td className="px-5 py-4"><button className="font-semibold text-forest" onClick={()=>setSelected(c)}>Manage</button></td></tr>})}</tbody></table>{filtered.length===0&&<div className="p-10 text-center text-sm text-ink/45">No coupons match your filters.</div>}</div>
 {selected&&<Modal title={"Coupon "+selected.code} onClose={()=>setSelected(null)}><div className="mt-6 rounded-[24px] bg-cream p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row"><div><div className="text-xs text-ink/40">Discount</div><div className="mt-2 text-3xl font-semibold text-forest">{couponMoney(selected)}</div><div className="mt-1 text-sm text-ink/50">{selected.description}</div></div><Badge>{couponExpired(selected.expires)?"Expired":selected.active?"Active":"Inactive"}</Badge></div></div><div className="mt-5 grid gap-4 sm:grid-cols-3"><div className="rounded-2xl border border-black/5 p-4"><div className="text-xs text-ink/40">Redemptions</div><div className="mt-1 text-xl font-semibold text-forest">{selected.redemptions} / {selected.usageLimit}</div></div><div className="rounded-2xl border border-black/5 p-4"><div className="text-xs text-ink/40">Minimum spend</div><div className="mt-1 font-semibold">{selected.minSpend?money(selected.minSpend):"None"}</div></div><div className="rounded-2xl border border-black/5 p-4"><div className="text-xs text-ink/40">Expiry</div><div className="mt-1 font-semibold">{selected.expires}</div></div></div><div className="mt-6 flex flex-wrap gap-3"><button className="btn-primary" disabled={couponExpired(selected.expires)||selected.redemptions>=selected.usageLimit} onClick={()=>redeem(selected.id)}>Record demo redemption</button><button className="btn-secondary" onClick={()=>{openEdit(selected);setSelected(null)}}>Edit coupon</button><button className="btn-secondary" onClick={()=>toggle(selected.id)}>{selected.active?"Deactivate":"Activate"}</button><button className="rounded-xl border border-red-200 px-4 py-2.5 text-sm font-semibold text-red-700" onClick={()=>remove(selected.id)}>Delete</button></div></Modal>}
 {(adding||editing)&&<Modal title={editing?"Edit coupon":"Create coupon"} onClose={()=>{setAdding(false);setEditing(null)}}><div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="text-sm">Coupon code<input className="input mt-2 uppercase" value={form.code} onChange={e=>setForm({...form,code:e.target.value.toUpperCase()})} placeholder="WELCOME10"/></label><label className="text-sm">Description<input className="input mt-2" value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="New guest discount"/></label><label className="text-sm">Discount type<select className="input mt-2" value={form.type} onChange={e=>setForm({...form,type:e.target.value as CouponType})}><option>Percentage</option><option>Fixed</option></select></label><label className="text-sm">Discount value<input className="input mt-2" type="number" min="1" max={form.type==="Percentage"?100:undefined} value={form.value} onChange={e=>setForm({...form,value:Number(e.target.value)})}/></label><label className="text-sm">Minimum spend<input className="input mt-2" type="number" min="0" value={form.minSpend} onChange={e=>setForm({...form,minSpend:Number(e.target.value)})}/></label><label className="text-sm">Expiry date<input className="input mt-2" type="date" value={form.expires?new Date(form.expires).toISOString().slice(0,10):""} onChange={e=>setForm({...form,expires:e.target.value?new Date(e.target.value+"T00:00:00").toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"}):""})}/></label><label className="text-sm">Usage limit<input className="input mt-2" type="number" min="1" value={form.usageLimit} onChange={e=>setForm({...form,usageLimit:Number(e.target.value)})}/></label><label className="flex items-center justify-between rounded-xl border border-black/5 bg-cream p-4 text-sm"><span><span className="font-semibold text-forest">Active</span><span className="mt-1 block text-xs text-ink/45">Allow guests to use this coupon.</span></span><input type="checkbox" checked={form.active} onChange={e=>setForm({...form,active:e.target.checked})} className="h-5 w-5"/></label></div><div className="mt-6 flex justify-end gap-3"><button className="btn-secondary" onClick={()=>{setAdding(false);setEditing(null)}}>Cancel</button><button className="btn-primary" onClick={saveCoupon}>{editing?"Save changes":"Create coupon"}</button></div></Modal>}
 </>;
}

